def verify_recovery_page(
    checkpoint: bytes,
    page: dict,
    keyring: dict,
    moment: int,
    cursor: dict | None = None,
) -> dict:
    """Verify one recovery audit page against a signed checkpoint, offline.

    Neither the audit nor any other file is read: only the checkpoint
    bytes, the page dict, the keyring, the current ``moment`` and the
    optional ``cursor`` returned by the previous page are consulted.
    The checkpoint is first parsed and its HMAC-SHA256 verified against
    the key the keyring binds to the exact issuer and version named in
    its payload (no fallback), and its ``moment`` must equal this
    verification moment.

    The first call passes no cursor: the page's ``after`` must then be
    zero.  Every later call passes the previous result's ``next``
    cursor; the page's ``after`` must equal that cursor's ``next`` and
    the cursor's ``digest`` must equal this checkpoint's digest, so a
    cursor can never resume a different checkpoint.  Each page's
    records must be contiguous, correctly ordered and hash-chained
    from the page's ``after`` position, and verification never runs
    past the checkpoint's signed ``lastSeq``.  Before that last seq is
    reached an empty page, a gap, a reordering, a duplicate or a
    mismatched predecessor is rejected as an invalid page.

    On success a fresh dict is returned with the key order ``digest``,
    ``lastSeq``, ``status`` and ``tail``: the checkpoint digest, the
    seq the verified prefix currently ends at, its tail hash and the
    status.  Reaching the signed chain tail yields ``"verified"``; any
    earlier page yields ``"continue"``.  An empty checkpoint (last
    seq 0, zero tail) accepts only an empty page starting at zero and
    directly reports seq 0, the zero hash and ``"verified"``.

    Type faults in the arguments or page fields raise :class:`TypeError`
    (a :class:`bool` never poses as an int); keyring structure or
    format faults raise :class:`ValueError`.  Checkpoint format or
    signature faults raise :class:`InvalidRecoveryCheckpointError` and
    page or cursor format or continuity faults raise
    :class:`InvalidRecoveryPageError`; both are :class:`ValueError`
    subclasses.  No input is modified.
    """
    validated_keyring = _validated_keyring(keyring)
    if isinstance(moment, bool) or not isinstance(moment, int):
        raise TypeError("moment must be an int")
    if moment < 0:
        raise ValueError("moment must be non-negative")
    if cursor is not None:
        if not isinstance(cursor, dict):
            raise TypeError("cursor must be a dict or None")
        if set(cursor.keys()) != _CURSOR_KEYS:
            raise _page_invalid(
                "cursor must contain exactly the keys 'digest' and 'next'"
            )
        cursor_digest = cursor[CP_DIGEST]
        cursor_next = cursor[NEXT]
        if not isinstance(cursor_digest, str) or not _is_digest(cursor_digest):
            raise _page_invalid(
                "cursor digest must be 64 lowercase hex characters"
            )
        if isinstance(cursor_next, bool) or not isinstance(cursor_next, int):
            raise _page_invalid("cursor next must be an int")
        if cursor_next < 0:
            raise _page_invalid("cursor next must be >= 0")

    payload, signature = _parse_checkpoint(checkpoint)
    checkpoint_digest = hashlib.sha256(checkpoint).hexdigest()
    issuer = payload[CP_ISSUER]
    key_version = payload[CP_KEY_VERSION]
    entry = _select_checkpoint_key(validated_keyring, issuer, key_version)
    expected_signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _checkpoint_payload_bytes(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        raise _checkpoint_invalid("signature does not match the payload")
    if payload[CP_MOMENT] != moment:
        raise _checkpoint_invalid(
            "checkpoint moment does not match the verification moment"
        )

    if cursor is not None and cursor_digest != checkpoint_digest:
        raise _page_invalid("cursor is bound to a different checkpoint")

    validated_page = _validated_page(page)
    after = validated_page[AFTER]
    records = validated_page[RECORDS]
    next_seq = validated_page[NEXT]

    if cursor is None:
        if after != 0:
            raise _page_invalid("the first page must start after 0")
    elif after != cursor_next:
        raise _page_invalid("page after must equal the cursor next")

    signed_last_seq = payload[CP_LAST_SEQ]
    signed_tail = payload[CP_TAIL]
    if after > signed_last_seq:
        raise _page_invalid(
            "page after must not exceed the checkpoint lastSeq"
        )
    if next_seq > signed_last_seq:
        raise _page_invalid(
            "page must not cross the signed lastSeq"
        )

    # The first record of a non-first page must chain onto the previous
    # page's last record hash; the first page's first record chains from
    # the zero hash.  Records within the page were already chained by
    # _validated_page once the opening predecessor is known.
    if records:
        opening_prev = (
            _RECOVERY_AUDIT_ZERO_HASH if after == 0 else None
        )
        if opening_prev is not None and records[0]["prev"] != opening_prev:
            raise _page_invalid(
                "the first record must chain from the zero hash"
            )

    # Before the signed tail is reached an empty page is a gap, not a
    # legitimate boundary: the verifier must be able to continue to the
    # end, and nothing may silently truncate the prefix.
    if next_seq < signed_last_seq:
        if not records:
            raise _page_invalid(
                "an empty page is not valid before the signed lastSeq"
            )
        if not validated_page[COMPLETE]:
            # A mid-chain page may legitimately claim more records
            # follow; only the boundary rules above apply.
            pass
        status = _VERIFY_CONTINUE
        current_tail = records[-1]["hash"]
    else:
        status = _VERIFY_VERIFIED
        current_tail = records[-1]["hash"] if records else (
            _RECOVERY_AUDIT_ZERO_HASH if after == 0 else None
        )
        if current_tail is None:
            # A page ending exactly at the signed last seq with no
            # records only occurs when after already equals lastSeq;
            # the tail then cannot be derived from this page, but such
            # a page is only valid for the empty checkpoint case.
            raise _page_invalid(
                "an empty final page is only valid for an empty checkpoint"
            )
        if current_tail != signed_tail:
            raise _page_invalid(
                "the final record hash does not match the signed tail"
            )

    return {
        CP_DIGEST: checkpoint_digest,
        CP_LAST_SEQ: next_seq,
        STATUS: status,
        CP_TAIL: current_tail,
    }

