def _parse_page(page: dict) -> tuple[int, int, bool, list]:
    """Validate one offline page dict into ``(after, next, complete, records)``.

    The container itself is type-checked by the caller.  Field type
    faults raise :class:`TypeError`; key-set, range, domain, gap,
    reordering, duplicate and chain faults raise
    :class:`InvalidRecoveryPageError`.
    """
    if set(page.keys()) != _PAGE_KEYS:
        raise _page_invalid(
            "page must contain exactly the keys 'after', 'complete', "
            "'next' and 'records'"
        )
    after = page[AFTER]
    next_seq = page[NEXT]
    complete = page[COMPLETE]
    records = page[RECORDS]
    for key, value in ((AFTER, after), (NEXT, next_seq)):
        if isinstance(value, bool) or not isinstance(value, int):
            raise _page_field_type_error(f"{key} must be an int")
        if value < 0:
            raise _page_invalid(f"{key} must be >= 0")
    if not isinstance(complete, bool):
        raise _page_field_type_error("complete must be a bool")
    if not isinstance(records, list):
        raise _page_field_type_error("records must be an array")

    # The in-page seq numbering is 1-relative while checked; shift it to
    # the page's after position before comparing.
    _validated_page_records(records)
    if records:
        if [record["seq"] for record in records] != list(
            range(after + 1, after + 1 + len(records))
        ):
            raise _page_invalid(
                "records must be contiguous from after + 1 with no gap, "
                "duplicate or reordering"
            )
        expected_next = records[-1]["seq"]
    else:
        expected_next = after
    if next_seq != expected_next:
        raise _page_invalid(
            "next must be the last record seq, or after when the page is empty"
        )
    return after, next_seq, complete, records


def _parse_cursor(cursor: dict) -> tuple[str, int]:
    """Validate a resume cursor into ``(checkpoint_digest, next)``."""
    if set(cursor.keys()) != _CURSOR_KEYS:
        raise _page_invalid(
            "cursor must contain exactly the keys 'digest' and 'next'"
        )
    cursor_digest = cursor[CP_DIGEST]
    cursor_next = cursor[NEXT]
    if not isinstance(cursor_digest, str):
        raise _page_field_type_error("cursor digest must be a str")
    if not _is_digest(cursor_digest):
        raise _page_invalid(
            "cursor digest must be 64 lowercase hex characters"
        )
    if isinstance(cursor_next, bool) or not isinstance(cursor_next, int):
        raise _page_field_type_error("cursor next must be an int")
    if cursor_next < 0:
        raise _page_invalid("cursor next must be >= 0")
    return cursor_digest, cursor_next


def verify_recovery_page(
    checkpoint: bytes,
    page: dict,
    keyring: dict,
    moment: int,
    cursor: dict | None = None,
) -> dict:
    """Verify one recovery audit page against a signed checkpoint, offline.

    Neither the audit nor any other file is read: only the checkpoint
    bytes, the page dict, the keyring, the current ``moment`` and the
    optional resume ``cursor`` are consulted.  The checkpoint is parsed
    and its HMAC-SHA256 is verified against the key the keyring binds to
    the exact issuer and version named in its payload, with no
    fallback; its ``moment`` must equal the given ``moment``.

    The first call passes no cursor, and the page's ``after`` must be
    zero.  Every later call passes ``{"digest", "next"}`` built from
    the previous result: the page's ``after`` must equal the cursor's
    ``next`` and the cursor's ``digest`` must equal this checkpoint's
    digest, so a cursor can never resume a different checkpoint.  Each
    page's records must be contiguous from ``after + 1`` -- a gap,
    reordering or duplicate is rejected -- correctly hash-chained to
    their predecessor and self-consistent at the paging boundaries;
    verification never crosses the signed ``lastSeq``.  Before that
    last seq is reached an empty page or a page whose ``complete``
    flag disagrees with the boundary is rejected.

    On success a fresh dict is returned with the key order ``digest``,
    ``lastSeq``, ``status`` and ``tail``: the checkpoint digest (the
    lowercase hex SHA-256 of the checkpoint bytes), the seq the
    verified prefix ends at, its tail hash and the status.  Reaching
    the signed chain tail yields ``"verified"``; every earlier page
    yields ``"continue"``.  An empty page presented again once the
    tail is reached reports the signed tail directly.  An empty
    checkpoint (last seq 0, zero tail) accepts only an empty page
    starting at zero and directly reports seq 0, the zero hash and
    ``"verified"``.

    Type faults in the arguments or fields raise :class:`TypeError`
    (a :class:`bool` never poses as an int); keyring structure or
    format faults raise :class:`ValueError`.  Checkpoint format,
    moment or signature faults raise
    :class:`InvalidRecoveryCheckpointError` and page or cursor format
    and continuity faults raise :class:`InvalidRecoveryPageError`;
    unknown credentials also raise :class:`AuthenticationError`.
    Both format errors are :class:`ValueError` subclasses.  No input
    is modified and no file is read or written.
    """
    if not isinstance(checkpoint, bytes):
        raise TypeError("checkpoint must be bytes")
    if not isinstance(page, dict):
        raise TypeError("page must be a dict")
    if cursor is not None and not isinstance(cursor, dict):
        raise TypeError("cursor must be a dict or None")
    validated_keyring = _validated_keyring(keyring)
    if isinstance(moment, bool) or not isinstance(moment, int):
        raise TypeError("moment must be an int")
    if moment < 0:
        raise ValueError("moment must be non-negative")

    cursor_digest: str | None = None
    cursor_next: int | None = None
    if cursor is not None:
        cursor_digest, cursor_next = _parse_cursor(cursor)

    payload, signature = _parse_checkpoint(checkpoint)
    checkpoint_digest = hashlib.sha256(checkpoint).hexdigest()
    issuer = payload[CP_ISSUER]
    key_version = payload[CP_KEY_VERSION]
    entry = _select_checkpoint_key(validated_keyring, issuer, key_version)
    expected_signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _checkpoint_payload_bytes(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        raise AuthenticationError("checkpoint signature does not match")
    if payload[CP_MOMENT] != moment:
        raise _checkpoint_invalid(
            "moment does not match the moment bound by the checkpoint"
        )

    if cursor_digest is not None and cursor_digest != checkpoint_digest:
        raise _page_invalid("cursor is bound to a different checkpoint")

    after, next_seq, complete, records = _parse_page(page)
    if cursor is None:
        if after != 0:
            raise _page_invalid("the first page must start after 0")
    elif after != cursor_next:
        raise _page_invalid("page after must equal the cursor next")

    signed_last_seq = payload[CP_LAST_SEQ]
    signed_tail = payload[CP_TAIL]
    if after > signed_last_seq:
        raise _page_invalid("page after must not exceed the checkpoint lastSeq")
    if next_seq > signed_last_seq:
        raise _page_invalid("page must not cross the signed lastSeq")

    # The first page opens the chain at the zero hash.  A later page's
    # opening predecessor belongs to the previous page, which the
    # caller does not pass; as with replication batches only its hash
    # shape is required there, while the in-page chain and the signed
    # tail anchor are checked exactly.
    if records and after == 0 and records[0]["prev"] != _RECOVERY_AUDIT_ZERO_HASH:
        raise _page_invalid("the first record must chain from the zero hash")

    at_tail = next_seq == signed_last_seq
    if complete != at_tail:
        raise _page_invalid(
            "complete must be true exactly when the page reaches the "
            "signed lastSeq"
        )
    if not at_tail:
        # Before the signed tail is reached an empty page is a gap, not
        # a legitimate boundary: nothing may silently truncate the chain.
        if not records:
            raise _page_invalid(
                "an empty page is not valid before the signed lastSeq"
            )
        return {
            CP_DIGEST: checkpoint_digest,
            CP_LAST_SEQ: next_seq,
            STATUS: _VERIFY_CONTINUE,
            CP_TAIL: records[-1]["hash"],
        }

    if records:
        current_tail = records[-1]["hash"]
        if current_tail != signed_tail:
            raise _page_invalid(
                "the final record hash does not match the signed tail"
            )
    else:
        # An empty page at the tail (after already equals lastSeq) only
        # restates the anchored boundary; its tail comes from the
        # checkpoint.  This is also the only form an empty checkpoint
        # accepts: first round, after zero, no records.
        current_tail = signed_tail
    return {
        CP_DIGEST: checkpoint_digest,
        CP_LAST_SEQ: signed_last_seq,
        STATUS: _VERIFY_VERIFIED,
        CP_TAIL: current_tail,
    }
